src = open("作業/body_src.html", encoding="utf-8").read()
out = []
for m in re.finditer(r'<section data-sec="(\d+)"[^>]*>(.*?)</section>', src, re.S):
    k, body = m.group(1), m.group(2)
    t, ref, job, eff, so = meta[k]
    body = re.sub(r"<!--.*?-->", "", body, flags=re.S)
    lines = []
    for e in re.findall(r"<(?:h1|h2|h3|p|blockquote|summary|div class=\"a\"|div class=\"warn\"|div class=\"row\"|div class=\"st\"|div><b>|a class=\"cta\"|a class=\"set[^\"]*\"|div class=\"byline\")[^>]*>(.*?)</(?:h1|h2|h3|p|blockquote|summary|div|a)>", body, re.S):
        s = html.unescape(re.sub(r"<br>", "／", re.sub(r"<(?!br)[^>]+>", "", e))).strip()
        if s and s not in lines: lines.append(s + (" <!-- 掘った: 記事の文そのもの（`grep -n ほとんど 作業/body_src.html` の1行。動画の「腰を外から押すものはありません」） -->" if "ほとんど" in s else ""))
    out.append(f"### {t}\n- 参考: {ref}\n- 仕事: {job}\n- 効果: {eff}\n- 文:\n" + "\n".join("  - " + s for s in lines) + f"\n- 出どころ: {so}\n")
